function continuationFromPreview(preview) {
  const operation = preview.operations[0];
  return {
    authority_digest: preview.authority_digest,
    child_operation_digest: operation.receipt_logical_operation_digest,
    child_operation_id: operation.operation_id,
    decision_digest: preview.decision_digest,
    preview_id: preview.preview_id,
    receipt_operation_digest: operation.receipt_logical_operation_digest,
    receipt_operation_id: 'operation-recovery-test',
    safety_mode: programme.WRITE_SAFETY_MODE,
  };
}
function replaceEvidence(value, pathParts, replacement) {
  const next = clone(value);
  let cursor = next;
  for (let index = 0; index < pathParts.length - 1; index += 1) cursor = cursor[pathParts[index]];
  cursor[pathParts[pathParts.length - 1]] = replacement;
  return withEvidenceDigest(next);
}

