test('partial write classifications require the same preview, authority, operation, and receipt binding', () => {
  const before = makeEvidence();
  const first = programme.projectionBootstrapRecovery.preview({ decision, evidence: before });
  assert.equal(first.ok, true, first.code);
  const continuation = continuationFromPreview(first);
  const childWritten = makeEvidence('CHILD_WRITTEN_PARENT_STALE', continuation);
  const continuationPreview = programme.projectionBootstrapRecovery.preview({ decision, evidence: childWritten });
  assert.equal(continuationPreview.ok, true, continuationPreview.code);
  assert.equal(continuationPreview.operation_count, 1);
  assert.deepEqual(continuationPreview.operation_order, [240]);
  const badContinuation = clone(childWritten);
  badContinuation.continuation.preview_id = 'f'.repeat(64);
  assert.equal(programme.projectionBootstrapRecovery.preview({ decision, evidence: withEvidenceDigest(badContinuation) }).ok, false);
  const badChildOperationDigest = clone(childWritten);
  badChildOperationDigest.continuation.child_operation_digest = 'f'.repeat(64);
  assert.equal(programme.projectionBootstrapRecovery.preview({ decision, evidence: withEvidenceDigest(badChildOperationDigest) }).ok, false);
  const wrongCombo = clone(before);
  wrongCombo.child.raw_body = continuationPreview.target.bodies.child;
  wrongCombo.child.body_digest = digestText(wrongCombo.child.raw_body);
  wrongCombo.child.canonical_digest = continuationPreview.target.canonical_digest;
  const wrongParsed = programme.parseChildV5Body(wrongCombo.child.raw_body, { repository, parent_issue: 240 });
  wrongCombo.child.projection = wrongParsed.envelope;
  wrongCombo.child.prefix_digest = wrongParsed.prefix_digest;
  wrongCombo.child.suffix_digest = wrongParsed.suffix_digest;
  wrongCombo.snapshot = 'BEFORE_CHILD';
  assert.equal(programme.projectionBootstrapRecovery.preview({ decision, evidence: withEvidenceDigest(wrongCombo) }).ok, false);
});

test('observable both-target snapshot returns zero operations', () => {
  const before = makeEvidence();
  const first = programme.projectionBootstrapRecovery.preview({ decision, evidence: before });
  const bothTarget = makeEvidence('PARENT_AND_CHILD_TARGET_OBSERVED', continuationFromPreview(first));
  const classification = programme.classifyPartialState({
    parent_canonical_digest: bothTarget.parent.canonical_digest,
    child_canonical_digest: bothTarget.child.canonical_digest,
    source_canonical_digest: programme.SOURCE_CANONICAL_DIGEST,
    target_canonical_digest: bothTarget.parent.canonical_digest,
  });
  assert.equal(classification.ok, true, classification.code);
  assert.equal(classification.classification, 'PARENT_AND_CHILD_TARGET_OBSERVED');
  const reconciled = programme.projectionBootstrapRecovery.preview({ decision, evidence: bothTarget });
  assert.equal(reconciled.ok, true, reconciled.code);
  assert.equal(reconciled.code, 'PROGRAMME_ZERO_DELTA');
  assert.equal(reconciled.operation_count, 0);
  assert.deepEqual(reconciled.operations, []);
  assert.equal(reconciled.recovery_retired, true);
  assert.equal(reconciled.duplicate_write, false);
  assert.equal(reconciled.readback_required, true);
});

test('self-retirement rejects a target with an unrelated canonical change', () => {
  const before = makeEvidence();
  const first = programme.projectionBootstrapRecovery.preview({ decision, evidence: before });
  const target = makeEvidence('PARENT_AND_CHILD_TARGET_OBSERVED', continuationFromPreview(first));
  const changed = clone(target);
  changed.parent.state.children.find((item) => item.issue === 360).summary = 'unrelated movement';
  assert.equal(programme.validateEvidence(withEvidenceDigest(changed), decision).ok, false);
});

test('receipt subsystem remains unchanged and the binding is truthful idempotent semantics', () => {
  const receiptPath = path.join(__dirname, '..', 'scripts', 'toolkit-github-program-receipt.cjs');
  const before = digestText(fs.readFileSync(receiptPath, 'utf8'));
  const descriptor = programme.buildReceiptOperationDescriptor({
    issue: 359,
    authority_digest: decision.web_authority.digest,
    source_body_digest: programme.SOURCE_CHILD_BODY_DIGEST,
    source_revision: programme.SOURCE_CHILD_REVISION,
    target_body_digest: 'f'.repeat(64),
  });
  assert.doesNotThrow(() => receipt.validateOperationDescriptor(descriptor));
  assert.equal(descriptor.operation_kind, 'IDEMPOTENT_SET');
  assert.equal(descriptor.safety_class, 'IDEMPOTENT');
  assert.equal(descriptor.cas_digest, programme.digestValue({
    mode: programme.WRITE_SAFETY_MODE,
    authority_digest: decision.web_authority.digest,
    source_body_digest: programme.SOURCE_CHILD_BODY_DIGEST,
    source_revision: programme.SOURCE_CHILD_REVISION,
  }));
  assert.equal(descriptor.adapter_identity_digest, programme.digestValue({
    adapter: 'github-web-readonly-adapter',
    mode: programme.WRITE_SAFETY_MODE,
    provider_cas_claim: false,
  }));
  assert.equal(receipt.OPERATION_KINDS.includes('CONDITIONAL_PROVIDER_UPDATE'), true);
  assert.equal(receipt.SAFETY_CLASSES.includes('CAS'), true);
  assert.equal(programme.WRITE_SAFETY_MODE, 'WEB_EXCLUSIVE_SINGLE_WRITER_RECOVERY_WINDOW');
  assert.equal(digestText(fs.readFileSync(receiptPath, 'utf8')), before);
});

test('bootstrap proof uses workspace bytes and never requires a historical Git object', (t) => {
  const bootstrapPath = path.join(__dirname, '..', '..', '.github', 'ai-agent-toolkit-programme.json');
  if (!fs.existsSync(bootstrapPath)) {
    t.skip('bootstrap commit B is intentionally absent during source commit validation');
    return;
  }
  const bootstrap = JSON.parse(fs.readFileSync(bootstrapPath, 'utf8'));
  const contractPath = path.join(__dirname, '..', 'contracts', 'github-program-reconciler', 'programme-surface-contract-v5.json');
  const contract = JSON.parse(fs.readFileSync(contractPath, 'utf8'));
  if (bootstrap.toolkit_package_version !== contract.toolkit_package_version) {
    assert.equal(bootstrap.toolkit_package_version, '2.10.8');
    assert.equal(programme.validateControllerBootstrap(bootstrap).ok, false);
    t.skip('source commit intentionally precedes the bootstrap-only package and source pin update');
    return;
  }
  const proof = programme.verifyBootstrapWorkspaceProof({
    bootstrap,
    contract_bytes: fs.readFileSync(contractPath, 'utf8'),
    workspace_revision: bootstrap.toolkit_contract.revision,
  });
  assert.equal(proof.ok, true, proof.code);
  assert.equal(proof.historical_git_object_required, false);
  assert.equal(proof.actual_workspace_bytes, true);
  const source = fs.readFileSync(path.join(__dirname, '..', 'scripts', 'toolkit-github-program-state-v5.cjs'), 'utf8');
  assert.doesNotMatch(source, /git show|git cat-file|fetch-depth|unshallow/);
});

test('accepted shared facade exposes v5 recovery without a second reconciler', () => {
  assert.equal(governance.programmeV5.projectionBootstrapRecovery, programme.projectionBootstrapRecovery);
  const runtime = governance.createRuntime({ repository });
  assert.equal(runtime.programmeV5.projectionBootstrapRecovery, programme.projectionBootstrapRecovery);
  assert.equal(programme.programmeV5.projectionBootstrapRecovery, programme.projectionBootstrapRecovery);
});
